const row = $input.first().json;
const stdout = String(row.stdout ?? '').trim();
const lastLine = stdout.split(/\r?\n/).filter(Boolean).at(-1) ?? '';
const match = lastLine.match(/^(\/workspace\/outputs\/resale-pilot\/.*?\.xlsx)\s+(\d+)\s+(\d+)$/);
return [{json:{status: match ? 'SUCCESS' : 'FAILED', output_xlsx: match?.[1] ?? '', target_count: Number(match?.[2] ?? 0), observation_count: Number(match?.[3] ?? 0), stdout, stderr: String(row.stderr ?? ''), finished_at_kst: $now.setZone('Asia/Seoul').toISO()}}];
